const cliente = $('Loop Clientes Balan?o').first().json;
const stats = $input.first().json;

const mesAnterior = new Date();
mesAnterior.setMonth(mesAnterior.getMonth() - 1);
const nomeMes = mesAnterior.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });

const relatorio = `Balan?o ${nomeMes} - ${cliente.nome_empresa}\n\nAtendimentos realizados: ${stats.total_mensagens || 0}\nContatos ?nicos: ${stats.total_contatos || 0}\nCarrinhos abertos: ${stats.carrinhos_ativos || 0}\n\nSeu agente de vendas trabalhou o m?s inteiro pra voc?! Qualquer d?vida estou aqui. ??`;

return [{ json: {
  cliente_id: cliente.cliente_id,
  instancia: cliente.instancia_whatsapp,
  evo_api_url: cliente.evo_api_url || 'https://evo.upviaagentes.com',
  evo_api_key: cliente.evo_api_key,
  telefone_proprietario: cliente.telefone_proprietario,
  nome_empresa: cliente.nome_empresa,
  relatorio,
  total_mensagens: Number(stats.total_mensagens) || 0,
  total_contatos: Number(stats.total_contatos) || 0,
  carrinhos_ativos: Number(stats.carrinhos_ativos) || 0,
  mes_referencia: nomeMes
} }];

const nichos = [
  "salão de beleza Pelotas",
  "clínica estética Pelotas",
  "dentista Pelotas",
  "manicure Pelotas",
  "salão de beleza Rio Grande RS",
  "clínica estética Porto Alegre",
  "consultório odontológico Pelotas"
];

const dataMin = new Date();
dataMin.setDate(dataMin.getDate() - 7);
const ad_delivery_date_min = dataMin.toISOString().split('T')[0];

return nichos.map(nicho => ({ json: { nicho, ad_delivery_date_min } }));

const regex = /(5[1-9]|[1-9][1-9])9?[6-9]\d{7}/;
const items = $input.all();
const resultados = [];

for (let i = 0; i < items.length; i++) {
  const nicho = $('Montar Lista de Nichos').itemMatching(i).json.nicho;
  const ads = items[i].json?.data || [];

  for (const ad of ads) {
    if (!ad.page_name || !ad.page_id) continue;

    const texto = ad.ad_creative_body || '';
    const digitos = texto.replace(/\D/g, '');
    const match = digitos.match(regex);

    let telefone = '';
    if (match) {
      telefone = match[0].length <= 11 ? '55' + match[0] : match[0];
    }

    resultados.push({
      json: {
        page_name: ad.page_name,
        page_id: ad.page_id,
        nicho,
        telefone,
        texto_anuncio: texto.slice(0, 500),
        data_captacao: new Date().toISOString()
      }
    });
  }
}

return resultados;

